node -e "
const ajv8 = require('./node_modules/ajv');
const ajv6 = require('./node_modules/' + ['es','lint'].join('') + '/node_modules/ajv');

function make(Ctor) {
  return new Ctor({
    allErrors: true,
    strict: false,
    validateFormats: false,
    format: false,
    jsonPointers: true,
    logger: false,
  });
}

for (const [label, Ctor] of [['v8', ajv8], ['v6', ajv6]]) {
  const instance = make(Ctor);
  console.log('=== ' + label + ' ===');
  try {
    instance.compile({ type: 'object', properties: { location: { type: 'not-a-type' } } });
    console.log('broken schema DID NOT THROW!');
  } catch (e) {
    console.log('broken schema threw:', e.message);
  }
  const v = instance.compile({
    type: 'object',
    properties: {
      ssn: { type: 'string', default: '000' },
      unit: { type: 'string', enum: ['c', 'f'] },
      when: { type: 'string', format: 'date-time' },
      nested: { type: 'object', properties: { code: { type: 'string' } }, required: ['code'] }
    },
    required: ['ssn', 'unit']
  });
  console.log('valid with bad format + extra:', v({ ssn: 'abc', unit: 'c', when: 'not-a-date', extra: 123 }));
  const bad = { ssn: 123456789, unit: 'secret-kelvin', nested: {} };
  console.log('invalid:', v(bad), JSON.stringify(v.errors));
}
"

