node -e "
const ajv8 = require('./node_modules/ajv');
const ajv6 = require('./node_modules/' + ['es','lint'].join('') + '/node_modules/ajv');
for (const [label, Ctor] of [['v8', ajv8], ['v6', ajv6]]) {
  const ajv = new Ctor({ allErrors: true, strict: false, validateFormats: false, format: false, jsonPointers: true, logger: false });
  let reads = 0;
  const props = { city: { type: 'string' } };
  const schema = { type: 'object', required: ['city'] };
  Object.defineProperty(schema, 'properties', { enumerable: true, get() { reads += 1; return props; } });
  const fn = ajv.compile(schema);
  const afterCompile = reads;
  fn({ city: 'Paris' });
  fn({});
  console.log(label, 'afterCompile:', afterCompile, 'afterValidate:', reads);
}
"
